import React from 'react';

function EtudiantPage() {
  return (
    <div className="p-4">
      <h1 className="text-2xl font-bold text-purple-500">Page des Étudiants</h1>
      <p>Liste des étudiants ou informations de l'étudiant connecté.</p>
    </div>
  );
}

export default EtudiantPage;
